import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"第一卦 乾 乾為天 乾上乾下","description":"周易 - 第一卦 乾 乾為天 乾上乾下","frontmatter":{"title":"第一卦 乾 乾為天 乾上乾下","description":"周易 - 第一卦 乾 乾為天 乾上乾下"},"headers":[],"relativePath":"classics/zhouyi/002.md","filePath":"classics/zhouyi/002.md"}'),l={name:"classics/zhouyi/002.md"};function p(n,a,t,d,s,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="乾" tabindex="-1">乾 <a class="header-anchor" href="#乾" aria-label="Permalink to “乾”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>元，亨，利，貞。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>潛龍，勿用。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>見龍再田，利見大人。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>君子終日乾乾，夕惕若，厲無咎。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>或躍在淵，無咎。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>飛龍在天，利見大人。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>亢龍有悔。用九：見群龍 無首，吉。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>大哉乾元，萬物資始，乃統天。雲行雨施，品物流形。大明始終，六位時成，時乘六龍以御天。乾道變化，各正性命，保合大和，乃利貞。首出庶物，萬國咸寧。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>天行健，君子以自強不息。</p><p>潛龍勿用，陽在下也。</p><p>見龍再田，德施普也。</p><p>終日乾乾，反覆道也。</p><p>或躍在淵，進無咎也。</p><p>飛龍在天，大人造也。</p><p>亢龍有悔，盈不可久也。</p><p>用九，天德不可為首也。</p><h2 id="文言" tabindex="-1">文言 <a class="header-anchor" href="#文言" aria-label="Permalink to “文言”">​</a></h2><p>「元者，善之長也，亨者，嘉之會也，利者，義之和也，貞者，事之幹也。君子體仁，足以長人；嘉會，足以合禮；利物，足以和義；貞固，足以幹事。君子行此四者， 故曰：乾：元亨利貞。」</p><h3 id="初九-1" tabindex="-1">初九 <a class="header-anchor" href="#初九-1" aria-label="Permalink to “初九”">​</a></h3><p>「潛龍勿用。」何謂也？子曰：「龍德而隱者也。不易乎世，不成乎名；遯世而無悶，不見是而無悶；樂則行之，憂則違之；確乎其不可拔，乾龍也。」</p><h3 id="九二-1" tabindex="-1">九二 <a class="header-anchor" href="#九二-1" aria-label="Permalink to “九二”">​</a></h3><p>「見龍在田，利見大人。」何謂也？子曰：「龍德而正中者也。庸言之信，庸行之謹，閒邪存其誠，善世而不伐，德博而化。易曰：「見龍在田，利見大人。」君德 也。」</p><h3 id="九三-1" tabindex="-1">九三 <a class="header-anchor" href="#九三-1" aria-label="Permalink to “九三”">​</a></h3><p>「君子終日乾乾，夕惕若，厲無咎。」何謂也？子曰：「君子進德修業，忠信，所以進德也。修辭立其誠，所以居業也。知至至之，可與幾也。知終終之，可與存義 也。是故，居上位而不驕，在下位而不憂。故乾乾，因其時而惕，雖危而無咎矣。」</p><h3 id="九四-1" tabindex="-1">九四 <a class="header-anchor" href="#九四-1" aria-label="Permalink to “九四”">​</a></h3><p>「或躍在淵，無咎。」何謂也？子曰：「上下無常，非為邪也。進退無恆，非離群也。君子進德修業，欲及時也，故無咎。」</p><h3 id="九五-1" tabindex="-1">九五 <a class="header-anchor" href="#九五-1" aria-label="Permalink to “九五”">​</a></h3><p>「飛龍在天，利見大人。」何謂也？子曰：「同聲相應，同氣相求；水流溼，火就燥；雲從龍，風從虎。聖人作，而萬物覩，本乎天者親上，本乎地者親下，則各從其 類也。</p><h3 id="上九-1" tabindex="-1">上九 <a class="header-anchor" href="#上九-1" aria-label="Permalink to “上九”">​</a></h3><p>「亢龍有悔。」何謂也？子曰：「貴而無位，高而無民，賢人在下而無輔，是以動而有悔也。」</p><p>乾龍勿用，下也。見龍在田，時舍也。終日乾乾，行事也。或躍在淵，自試也。飛龍在天，上治也。亢龍有悔，窮之災也。乾元用九，天下治也。</p><p>乾龍勿用，陽氣潛藏。見龍在田，天下文明。終日乾乾，與時偕行。或躍在淵，乾道乃革。飛龍在天，乃位乎天德。亢龍有悔，與時偕極。乾元用九，乃見天則。</p><p>乾元者，始而亨者也。利貞者，性情也。乾始能以美利利天下，不言所利。大矣哉！大哉乾乎？剛健中正，純粹精也。六爻發揮，旁通情也。時乘六龍，以御天也。雲行雨施，天 下平也。</p><p>君子以成德為行，日可見之行也。潛之為言也，隱而未見，行而未成，是以君子弗用也。</p><p>君子學以聚之，問以辯之，寬以居之，仁以行之。易曰：「見龍在田，利見大人。」君德也。</p><p>九三，重剛而不中，上不在天，下不在田。故乾乾，因其時而惕，雖危無咎矣。</p><p>九四，重剛而不中，上不在天，下不在田，中不在人，故或之。或之者，疑之也，故無咎。</p><p>夫大人者，與天地合其德，與日月合其明，與四時合其序，與鬼神合其吉凶。先天下而天弗違，後天而奉天時。天且弗違，而況於人乎？況於鬼神乎？</p><p>亢之為言也，知進而不知退，知存而不知亡，知得而不知喪。其唯聖人乎？知進退存亡，而不失其正者，其為聖人乎？</p>',49)])])}const f=e(l,[["render",p]]);export{b as __pageData,f as default};
